    for(size_t i=0;i<n;++i)require(f.lo[i]<=f.hi[i]&&f.hi[i]<=f.d&&f.offsets[i+1]>=f.offsets[i]&&f.offsets[i+1]-f.offsets[i]==bucket(f.hi[i]-f.lo[i]),"bad band");
